fn allocate_zeroed<T: Default + Clone + 'static>(
    heap: &mut SourceHeap,
    count: usize,
) -> Result<SourceMutPointer<T>, SourceHeapError> {
    let mut values = Vec::new();
    values
        .try_reserve_exact(count)
        .map_err(|_| SourceHeapError::AllocationFailed)?;
    values.resize(count, T::default());
    heap.allocate(values)
}

fn work_get<T: Clone + 'static>(
    heap: &SourceHeap,
    pointer: SourceMutPointer<T>,
    index: i32,
) -> Result<T, SourceHeapError> {
    let offset = usize::try_from(index).map_err(|_| SourceHeapError::PointerOutOfBounds)?;
    heap.slice(pointer.as_const())?
        .get(offset)
        .cloned()
        .ok_or(SourceHeapError::PointerOutOfBounds)
}

fn work_set<T: 'static>(
    heap: &mut SourceHeap,
    pointer: SourceMutPointer<T>,
    index: i32,
    value: T,
) -> Result<(), SourceHeapError> {
    let offset = usize::try_from(index).map_err(|_| SourceHeapError::PointerOutOfBounds)?;
    *heap
        .slice_mut(pointer)?
        .get_mut(offset)
        .ok_or(SourceHeapError::PointerOutOfBounds)? = value;
    Ok(())
}

fn bns_vertex(
    heap: &SourceHeap,
    p_bns: &BN_STRUCT,
    index: i32,
) -> Result<BNS_VERTEX, SourceHeapError> {
    let offset = usize::try_from(index).map_err(|_| SourceHeapError::PointerOutOfBounds)?;
    heap.slice(p_bns.vert.as_const())?
        .get(offset)
        .cloned()
        .ok_or(SourceHeapError::PointerOutOfBounds)
}

fn bns_edge(heap: &SourceHeap, p_bns: &BN_STRUCT, index: i32) -> Result<BNS_EDGE, SourceHeapError> {
    let offset = usize::try_from(index).map_err(|_| SourceHeapError::PointerOutOfBounds)?;
    heap.slice(p_bns.edge.as_const())?
        .get(offset)
        .cloned()
        .ok_or(SourceHeapError::PointerOutOfBounds)
}

fn bns_vertex_mut<'a>(
    heap: &'a mut SourceHeap,
    p_bns: &BN_STRUCT,
    index: i32,
) -> Result<&'a mut BNS_VERTEX, SourceHeapError> {
    let offset = usize::try_from(index).map_err(|_| SourceHeapError::PointerOutOfBounds)?;
    heap.slice_mut(p_bns.vert)?
        .get_mut(offset)
        .ok_or(SourceHeapError::PointerOutOfBounds)
}

fn bns_edge_mut<'a>(
    heap: &'a mut SourceHeap,
    p_bns: &BN_STRUCT,
    index: i32,
) -> Result<&'a mut BNS_EDGE, SourceHeapError> {
    let offset = usize::try_from(index).map_err(|_| SourceHeapError::PointerOutOfBounds)?;
    heap.slice_mut(p_bns.edge)?
        .get_mut(offset)
        .ok_or(SourceHeapError::PointerOutOfBounds)
}

fn bns_edge_index(
    heap: &SourceHeap,
    vertex: &BNS_VERTEX,
    index: i32,
) -> Result<i32, SourceHeapError> {
    let offset = usize::try_from(index).map_err(|_| SourceHeapError::PointerOutOfBounds)?;
    heap.slice(vertex.iedge.as_const())?
        .get(offset)
        .copied()
        .ok_or(SourceHeapError::PointerOutOfBounds)
}

fn is_bns_error(value: i32) -> bool {
    (BNS_ERR..=BNS_MAX_ERR_VALUE).contains(&value)
}

fn input_atom_ref(atoms: &[inp_ATOM], index: i32) -> Result<&inp_ATOM, SourceHeapError> {
    let offset = usize::try_from(index).map_err(|_| SourceHeapError::PointerOutOfBounds)?;
    atoms.get(offset).ok_or(SourceHeapError::PointerOutOfBounds)
}

fn input_atom_neighbor(atom: &inp_ATOM, index: i32) -> Result<i32, SourceHeapError> {
    let offset = usize::try_from(index).map_err(|_| SourceHeapError::PointerOutOfBounds)?;
    atom.neighbor
        .get(offset)
        .copied()
        .map(i32::from)
        .ok_or(SourceHeapError::PointerOutOfBounds)
}

fn input_atom_bond_type(atom: &inp_ATOM, index: i32) -> Result<i32, SourceHeapError> {
    let offset = usize::try_from(index).map_err(|_| SourceHeapError::PointerOutOfBounds)?;
    atom.bond_type
        .get(offset)
        .copied()
        .map(i32::from)
        .ok_or(SourceHeapError::PointerOutOfBounds)
}

fn input_atom_numh(atom: &inp_ATOM) -> i32 {
    i32::from(atom.num_H)
        + i32::from(atom.num_iso_H[0])
        + i32::from(atom.num_iso_H[1])
        + i32::from(atom.num_iso_H[2])
}

fn atom_parity_well_def(parity: i8) -> bool {
    i32::from(AB_MIN_WELL_DEFINED_PARITY as i8) <= i32::from(parity)
        && i32::from(parity) <= i32::from(AB_MAX_WELL_DEFINED_PARITY as i8)
}

fn input_atom_num_iso_h(atom: &inp_ATOM) -> i32 {
    i32::from(atom.num_iso_H[0]) + i32::from(atom.num_iso_H[1]) + i32::from(atom.num_iso_H[2])
}

#[allow(non_snake_case)]
fn MAX_AT_FLOW_SOURCE_MACRO(atom: &inp_ATOM) -> i32 {
    // BEGIN INCHI C MACRO: third_party/InChI/INCHI-1-SRC/INCHI_BASE/src/ichi_bns.h:172 MAX_AT_FLOW
    // INCHI✔️✔️: #if ( ADD_CAPACITY_RADICAL == 1 )  /* { */
    // INCHI✔️✔️: #define MAX_AT_FLOW(X) (((X).chem_bonds_valence - (X).valence)+\
    // INCHI✔️✔️:                        ((is_centerpoint_elem((X).el_number)||get_endpoint_valence((X).el_number))?\
    // INCHI✔️✔️:                            (((X).radical==RADICAL_DOUBLET)/*+2*((X).radical==RADICAL_TRIPLET)*/):0))
    // INCHI❌❌: #else /* } ADD_CAPACITY_RADICAL { */
    // INCHI❌❌: #define MAX_AT_FLOW(X) (((X).chem_bonds_valence - (X).valence)
    // INCHI✔️✔️: #endif  /* } ADD_CAPACITY_RADICAL */
    // END INCHI C MACRO: MAX_AT_FLOW
    // BEGIN INCHI ACTIVE MACRO CONFIGURATION: MAX_AT_FLOW
    // INCHI✔️✔️: #define ADD_CAPACITY_RADICAL 1
    // INCHI✔️✔️: #define RADICAL_DOUBLET 2
    // END INCHI ACTIVE MACRO CONFIGURATION: MAX_AT_FLOW

    let base = i32::from(atom.chem_bonds_valence) - i32::from(atom.valence);
    if ADD_CAPACITY_RADICAL == 1
        && (is_centerpoint_elem(atom.el_number) != 0 || get_endpoint_valence(atom.el_number) != 0)
        && atom.radical == RADICAL_DOUBLET as i8
    {
        base + 1
    } else {
        base
    }
}

