const PR_SIMPLE_MSK: i32 = (att_bit(ATTOT_NUM_NP_PROTON) | att_bit(ATTOT_NUM_OH_PLUS)) as i32;
const AR_SIMPLE_MSK1: i32 = att_bit(ATTOT_NUM_COH)
    | att_bit(ATTOT_NUM_CSH)
    | att_bit(ATTOT_NUM_OOH)
    | att_bit(ATTOT_NUM_ZOOH)
    | att_bit(ATTOT_NUM_NOH)
    | att_bit(ATTOT_NUM_HAL_ACID);
const AR_TYP_MASK: [i32; 8] = [AR_SIMPLE_TYP1 as i32, AR_SIMPLE_MSK1, 0, 0, 0, 0, 0, 0];
const AA_SIMPLE_MSK1: i32 = att_bit(ATTOT_NUM_CO_MINUS)
    | att_bit(ATTOT_NUM_CS_MINUS)
    | att_bit(ATTOT_NUM_OO_MINUS)
    | att_bit(ATTOT_NUM_ZOO_MINUS)
    | att_bit(ATTOT_NUM_NO_MINUS)
    | att_bit(ATTOT_NUM_O_MINUS)
    | att_bit(ATTOT_NUM_HAL_ANION);
const AA_SIMPLE_MSK4: i32 = att_bit(ATTOT_NUM_N_MINUS);
const AA_TYP_MASK: [i32; 10] = [
    AA_SIMPLE_TYP1 as i32,
    AA_SIMPLE_MSK1,
    AA_SIMPLE_TYP4 as i32,
    AA_SIMPLE_MSK4,
    0,
    0,
    0,
    0,
    0,
    0,
];
const ATBIT_MSK_NP: i32 = att_bit(ATTOT_NUM_NP_PLUS)
    | att_bit(ATTOT_NUM_NP_PROTON)
    | att_bit(ATTOT_NUM_NP_H)
    | att_bit(ATTOT_NUM_N_MINUS)
    | att_bit(ATTOT_NUM_NP);
const ATBIT_MSK_OS: i32 = att_bit(ATTOT_NUM_COH)
    | att_bit(ATTOT_NUM_CSH)
    | att_bit(ATTOT_NUM_ZOH)
    | att_bit(ATTOT_NUM_OOH)
    | att_bit(ATTOT_NUM_ZOOH)
    | att_bit(ATTOT_NUM_NOH)
    | att_bit(ATTOT_NUM_N_OH)
    | att_bit(ATTOT_NUM_CO)
    | att_bit(ATTOT_NUM_ZO)
    | att_bit(ATTOT_NUM_NO)
    | att_bit(ATTOT_NUM_N_O)
    | att_bit(ATTOT_NUM_CO_MINUS)
    | att_bit(ATTOT_NUM_CS_MINUS)
    | att_bit(ATTOT_NUM_ZO_MINUS)
    | att_bit(ATTOT_NUM_OO_MINUS)
    | att_bit(ATTOT_NUM_ZOO_MINUS)
    | att_bit(ATTOT_NUM_NO_MINUS)
    | att_bit(ATTOT_NUM_N_O_MINUS);
const AR_HARD_MSK_POS: i32 = ATBIT_MSK_NP;
const AR_HARD_MSK_NEG: i32 = ATBIT_MSK_NP | ATBIT_MSK_OS;
const AR_HARD_MSK_HA: i32 = att_bit(ATTOT_NUM_CO) | att_bit(ATTOT_NUM_NO);
const AR_HARD_MSK_HN: i32 = (ATBIT_MSK_NP | ATBIT_MSK_OS) & !AR_HARD_MSK_HA;
const AA_HARD_MSK_POS: i32 = ATBIT_MSK_NP;
const AA_HARD_MSK_NEG: i32 =
    (ATBIT_MSK_NP | ATBIT_MSK_OS) & !(att_bit(ATTOT_NUM_CO) | att_bit(ATTOT_NUM_NO));
const AA_HARD_MSK_CO: i32 = att_bit(ATTOT_NUM_CO) | att_bit(ATTOT_NUM_NO);
const AA_HARD_MSK_H: i32 = ATBIT_MSK_NP | ATBIT_MSK_OS;
const PR_HARD_MSK_POS: i32 = ATBIT_MSK_NP;
const PR_HARD_MSK_NEG: i32 = ATBIT_MSK_NP | ATBIT_MSK_OS;
const PR_HARD_MSK_H: i32 = ATBIT_MSK_NP | ATBIT_MSK_OS;

const fn att_bit(index: usize) -> i32 {
    1_i32 << index
}

fn finish_atom_charge_type(
    mut type_: i32,
    mask: i32,
    atom_charge: i8,
    delta: i32,
    count_mask_bits: bool,
    n_at_type_totals: Option<&mut [i32]>,
    p_mask: Option<&mut i32>,
) -> Result<i32, SourceHeapError> {
    let mut totals = n_at_type_totals;
    if count_mask_bits {
        if let Some(slice) = totals.as_deref_mut() {
            if mask != 0 && (mask & att_bit(ATTOT_NUM_ERRORS)) == 0 {
                for i in 0..ATTOT_ARRAY_LEN {
                    let bit = if i < 31 { att_bit(i) } else { 0 };
                    if (bit & mask) != 0 {
                        let total = slice
                            .get_mut(i)
                            .ok_or(SourceHeapError::PointerOutOfBounds)?;
                        *total = total.wrapping_add(delta);
                    }
                }
            }
            if atom_charge != 0 {
                let total_charge = slice
                    .get_mut(ATTOT_TOT_CHARGE)
                    .ok_or(SourceHeapError::PointerOutOfBounds)?;
                *total_charge =
                    total_charge.wrapping_add(delta.wrapping_mul(i32::from(atom_charge)));
                let charge_count = slice
                    .get_mut(ATTOT_NUM_CHARGES)
                    .ok_or(SourceHeapError::PointerOutOfBounds)?;
                *charge_count = charge_count.wrapping_add(delta);
            }
        }
        if let Some(mask_out) = p_mask {
            *mask_out = mask;
        }
    }

    if (mask & att_bit(ATTOT_NUM_ERRORS)) != 0 {
        type_ = 0;
        if let Some(slice) = totals.as_deref_mut() {
            let errors = slice
                .get_mut(ATTOT_NUM_ERRORS)
                .ok_or(SourceHeapError::PointerOutOfBounds)?;
            *errors = errors.wrapping_add(1);
        }
    }

    Ok(type_)
}

fn mark_forbidden_atom_edge(
    heap: &mut SourceHeap,
    pBNS: &BN_STRUCT,
    atom_index: i32,
    neighbor_slot: i32,
    edge_forbidden_mask: S_CHAR,
) -> Result<(), SourceHeapError> {
    let vertex = bns_vertex(heap, pBNS, atom_index)?;
    let edge_index = bns_edge_index(heap, &vertex, neighbor_slot)?;
    bns_edge_mut(heap, pBNS, edge_index)?.forbidden |= edge_forbidden_mask;
    Ok(())
}

