    // INCHI✔️❗:                         if (at->chem_bonds_valence > at->valence)
    // INCHI✔️❗:                         {
    // INCHI✔️❗:                             mask |= ( ATBIT_NP_Plus );         /* =N(+)=, #N(+)-, =N(+)< */
