    // INCHI✔️❌:     int tg_H_Other = 0;
    // INCHI✔️❌:     int tg_H_Acid = 0;
    // INCHI✔️❌:     int ret = 0, ret2;
    // INCHI✔️❌:     int nDelta, nNumMoved2AcidH = 0, nNumNeutralized = 0, nPrevNumCharges;
    // INCHI✔️❌:     int nPosCharges, nPosCharges2;
    // INCHI✔️❌:     int nNegCharges, nNegCharges2;
    // INCHI✔️❌:     nPosCharges = ( pAATG->nAtTypeTotals[ATTOT_NUM_CHARGES] + pAATG->nAtTypeTotals[ATTOT_TOT_CHARGE] ) / 2;
    // INCHI✔️❌:     nNegCharges = ( pAATG->nAtTypeTotals[ATTOT_NUM_CHARGES] - pAATG->nAtTypeTotals[ATTOT_TOT_CHARGE] ) / 2;
    // INCHI✔️❌:     pBNS->type_CN = ( BNS_VERT_TYPE_C_GROUP | BNS_VERT_TYPE_C_NEGATIVE );
    // INCHI✔️❌:     pBNS->type_T = BNS_VERT_TYPE_TGROUP;
    // INCHI✔️❌:     pBNS->type_TACN = BNS_VERT_TYPE_ACID;
    // INCHI✔️❌:     cg_Plus = CreateCGroupInBnStruct( at, num_atoms, pBNS, AR_HARD_TYP_POS, AR_HARD_MSK_POS, 1 );
    // INCHI✔️❌:     cg_Minus = CreateCGroupInBnStruct( at, num_atoms, pBNS, AR_HARD_TYP_NEG, AR_HARD_MSK_NEG, -1 );
    // INCHI✔️❌:     tg_H_Other = CreateTGroupInBnStruct( at, num_atoms, pBNS, AR_HARD_TYP_HN, AR_HARD_MSK_HN );
    // INCHI✔️❌:     tg_H_Acid = CreateTGroupInBnStruct( at, num_atoms, pBNS, AR_HARD_TYP_HA, AR_HARD_MSK_HA );
    // INCHI✔️❌:     if (tg_H_Other >= num_atoms && tg_H_Acid >= num_atoms) { /* move protons and neutralize ion pairs */ }
    // INCHI✔️❌:     if (tg_H_Acid >= num_atoms) { ret2 = RemoveLastGroupFromBnStruct( at, num_atoms, tg_H_Acid, pBNS ); if (!ret && ret2) ret = ret2; }
    // INCHI✔️❌:     if (tg_H_Other >= num_atoms) { ret2 = RemoveLastGroupFromBnStruct( at, num_atoms, tg_H_Other, pBNS ); if (!ret && ret2) ret = ret2; }
    // INCHI✔️❌:     if (cg_Minus >= num_atoms) { ret2 = RemoveLastGroupFromBnStruct( at, num_atoms, cg_Minus, pBNS ); if (!ret && ret2) ret = ret2; }
    // INCHI✔️❌:     if (cg_Plus >= num_atoms) { ret2 = RemoveLastGroupFromBnStruct( at, num_atoms, cg_Plus, pBNS ); if (!ret && ret2) ret = ret2; }
    // INCHI✔️❌:     pBNS->type_CN = 0; pBNS->type_T = 0; pBNS->type_TACN = 0;
    // INCHI✔️❌:     if (ret) { return ret; }
    // INCHI✔️❌:     nPosCharges2 = ( pAATG->nAtTypeTotals[ATTOT_NUM_CHARGES] + pAATG->nAtTypeTotals[ATTOT_TOT_CHARGE] ) / 2;
    // INCHI✔️❌:     nNegCharges2 = ( pAATG->nAtTypeTotals[ATTOT_NUM_CHARGES] - pAATG->nAtTypeTotals[ATTOT_TOT_CHARGE] ) / 2;
    // INCHI✔️❌:     if (( nPosCharges - nNegCharges ) - ( nPosCharges2 - nNegCharges2 ) != 0) { return BNS_PROGRAM_ERR; }
    // INCHI✔️❌:     if (nNumCanceledCharges) { *nNumCanceledCharges = 2 * nNumNeutralized; }
