pub(crate) fn GetVertexDegree(
    heap: &SourceHeap,
    pBNS: &BN_STRUCT,
    v: Vertex,
) -> Result<i32, SourceHeapError> {
    // BEGIN INCHI C FUNCTION: third_party/InChI/INCHI-1-SRC/INCHI_BASE/src/ichi_bns.c:9774 GetVertexDegree
    // INCHI✔️❌: int GetVertexDegree( BN_STRUCT* pBNS, Vertex v )
    // INCHI✔️❌: {
    // INCHI✔️❌:     int i = v / 2 - 1;
    // INCHI✔️❌:     if (i >= 0)
    // INCHI✔️❌:     {
    // INCHI✔️❌:         if (pBNS->vert[i].st_edge.cap > 0)
    // INCHI✔️❌:         {
    // INCHI✔️❌:             return pBNS->vert[i].num_adj_edges + 1; /* add 1 neighbor for s or t */
    // INCHI✔️❌:         }
    // INCHI✔️❌:         else
    // INCHI✔️❌:         {
    // INCHI✔️❌:             return 0;   /* since the edge s-v has zero capacity, we ignore vertex v */
    // INCHI✔️❌:         }
    // INCHI✔️❌:     }
    // INCHI✔️❌:     else
    // INCHI✔️❌:     {
    // INCHI✔️❌:         return pBNS->num_vertices;
    // INCHI✔️❌:     }
    // INCHI✔️❌: }
    // END INCHI C FUNCTION: GetVertexDegree

    let i = v / 2 - 1;
    if i >= 0 {
        let vertex = bns_vertex(heap, pBNS, i)?;
        if vertex.st_edge.cap > 0 {
            Ok(i32::from(vertex.num_adj_edges) + 1)
        } else {
            Ok(0)
        }
    } else {
        Ok(pBNS.num_vertices)
    }
}

