    // INCHI✔️❌:         if (at && v1 < pBNS->num_atoms)
    // INCHI✔️❌:         {
    // INCHI✔️❌:             delta = p1->st_edge.cap - p1->st_edge.flow + e->flow;
    // INCHI✔️❌:             rad = at[v1].radical;
