    // INCHI✔️❌:                 pEndp = pBNS->vert + vEndp;
    // INCHI✔️❌:                 ret = AddNewEdge( pRad, pEndp, pBNS, 1, edge_flow );
    // INCHI✔️❌:                 if (IS_BNS_ERROR( ret ))
