    // INCHI✔️❌:             ALTP_START_ATOM( pBNS->altp[i] ) = NO_VERTEX;
    // INCHI✔️❌:             ALTP_END_ATOM( pBNS->altp[i] ) = NO_VERTEX;
    // INCHI✔️❌:         }
    // INCHI✔️❌:     }
    // INCHI✔️❌:     pBNS->alt_path = NULL;
    // INCHI✔️❌:     pBNS->num_altp = 0;
    // INCHI✔️❌:     return i;
    // INCHI✔️❌: }
    // END INCHI C FUNCTION: ReInitBnStructAltPaths
    // BEGIN INCHI ACTIVE MACRO CONFIGURATION: ReInitBnStructAltPaths
    // INCHI✔️❌: #define BN_MAX_ALTP 16
    // INCHI✔️❌: #define NO_VERTEX -2
    // INCHI✔️❌: #define ALTP_DELTA(altp) (altp)[iALTP_FLOW].flow[0]
    // INCHI✔️❌: #define ALTP_PATH_LEN(altp) (altp)[iALTP_PATH_LEN].number
    // INCHI✔️❌: #define ALTP_START_ATOM(altp) (altp)[iALTP_START_ATOM].number
    // INCHI✔️❌: #define ALTP_END_ATOM(altp) (altp)[iALTP_END_ATOM].number
    // END INCHI ACTIVE MACRO CONFIGURATION: ReInitBnStructAltPaths

    let mut i = 0_i32;
    while i < pBNS.max_altp && i < BN_MAX_ALTP as i32 {
        let alt_path =
            pBNS.altp[usize::try_from(i).map_err(|_| SourceHeapError::PointerOutOfBounds)?];
        if !alt_path.is_null() {
            let path = heap.slice_mut(alt_path)?;
            path.get_mut(tagAltPathConst_iALTP_FLOW as usize)
                .ok_or(SourceHeapError::PointerOutOfBounds)?
                .set_flow(0, 0);
            path.get_mut(tagAltPathConst_iALTP_PATH_LEN as usize)
                .ok_or(SourceHeapError::PointerOutOfBounds)?
                .set_number(0);
            path.get_mut(tagAltPathConst_iALTP_START_ATOM as usize)
                .ok_or(SourceHeapError::PointerOutOfBounds)?
                .set_number(NO_VERTEX);
            path.get_mut(tagAltPathConst_iALTP_END_ATOM as usize)
                .ok_or(SourceHeapError::PointerOutOfBounds)?
                .set_number(NO_VERTEX);
        }
        i += 1;
    }
    pBNS.alt_path = SourceMutPointer::null();
    pBNS.num_altp = 0;
    Ok(i)
