        let mut vertex = bns_vertex(heap, pBNS, fictpoint)?;
        vertex.iedge = previous.iedge.offset(i64::from(previous.max_adj_edges))?;
        vertex.max_adj_edges = (i32::from(group.num_CPoints) + BNS_ADD_EDGES as i32) as AT_NUMB;
