#[allow(non_snake_case)]
pub(crate) fn ClearAllBnDataEdges(
    heap: &mut SourceHeap,
    e: SourceMutPointer<Edge>,
    value: Vertex,
    size: i32,
) -> Result<(), SourceHeapError> {
    // BEGIN INCHI C FUNCTION: third_party/InChI/INCHI-1-SRC/INCHI_BASE/src/ichi_bns.c:9620 ClearAllBnDataEdges
    // INCHI✔️❌: void ClearAllBnDataEdges( Edge *e, Vertex value, int size )
    // INCHI✔️❌: {
    // INCHI✔️❌:     int i;
    // INCHI✔️❌:     for (i = 0; i < size; i++)
    // INCHI✔️❌:     {
    // INCHI✔️❌:         e[i][0] = value;
    // INCHI✔️❌:     }
    // INCHI✔️❌: }
    // END INCHI C FUNCTION: ClearAllBnDataEdges

    for index in 0..size {
        let offset = usize::try_from(index).map_err(|_| SourceHeapError::PointerOutOfBounds)?;
        heap.slice_mut(e)?
            .get_mut(offset)
            .ok_or(SourceHeapError::PointerOutOfBounds)?[0] = value;
    }
    Ok(())
}

