    // INCHI✔️❌:
    // INCHI✔️❌:     if (pBNS->num_atoms != num_atoms || pBNS->num_vertices != num_atoms || pBNS->num_bonds != pBNS->num_edges)
    // INCHI✔️❌:     {
    // INCHI✔️❌:         ret = BNS_REINIT_ERR;
    // INCHI✔️❌:         goto exit_function;
    // INCHI✔️❌:     }
    // INCHI✔️❌:     if (bUnknAltAsNoStereo)
    // INCHI✔️❌:     {
    // INCHI✔️❌:         for (ibond = 0; ibond < num_bonds; ibond++)
    // INCHI✔️❌:         {
    // INCHI✔️❌:             pBond = pBNS->edge + ibond;
    // INCHI✔️❌:             if (pBond->nBondTypeInpAltBns != BT_ALTERN_BOND && pBond->nBondTypeInpAltBns != BT_IGNORE_BOND)
    // INCHI✔️❌:             {
    // INCHI✔️❌:                 continue;
    // INCHI✔️❌:             }
    // INCHI✔️❌:             iat1 = pBond->neighbor1;
    // INCHI✔️❌:             iat2 = pBond->neighbor12 ^ iat1;
    // INCHI✔️❌:             ib1 = pBond->neigh_ord[0];
    // INCHI✔️❌:             ib2 = pBond->neigh_ord[1];
    // INCHI✔️❌:             if ( /* alt bond non-adjacent to a taut. endpoint: */
    // INCHI✔️❌:                 ( pBond->nBondTypeInpAltBns == BT_ALTERN_BOND &&
    // INCHI✔️❌:                   pBond->nNumAtInBlockAltBns <= 3 )  /* non-ring bond */ ||
    // INCHI✔️❌:                  /* alt bond adjacent to a taut. endpoint: */
    // INCHI✔️❌:                   ( pBond->nBondTypeInpAltBns == BT_IGNORE_BOND &&
    // INCHI✔️❌:                  ( at[iat1].bond_type[ib1] & BOND_TYPE_MASK ) == BOND_ALTERN )
    // INCHI✔️❌:                  )
    // INCHI✔️❌:             {
    // INCHI✔️❌:                 if (( at[iat1].bond_type[ib1] & BOND_TYPE_MASK ) == BOND_ALTERN)
    // INCHI✔️❌:                 {
    // INCHI✔️❌:                     /* bond_type = BOND_ALT12NS; */
