    // INCHI✔️❌: {
    // INCHI✔️❌:     BNS_EDGE *pEdge = pBNS->edge + iedge;
    // INCHI✔️❌:     int       nMaxFlow = ( pEdge->cap & EDGE_FLOW_MASK ); /* edge cap */
