    // INCHI✔️❌: #define EDGE_FLOW_MASK 0x3fff
    // INCHI✔️❌: #define MAX_BOND_EDGE_CAP 2
    // END INCHI ACTIVE MACRO CONFIGURATION: nMaxFlow2Check

    let edge = bns_edge(heap, pBNS, iedge)?;
    let mut nMaxFlow = edge.cap & EDGE_FLOW_MASK as i32;
