    #[test]
    fn source_port__ichi_bns__markatomsattautgroups__line_1331() {
        fn make_markable_path(
            heap: &mut SourceHeap,
            group_type: AT_NUMB,
            vertices: &[usize],
            definitions: &[(usize, usize, i8)],
            atom_limit: usize,
        ) -> BN_STRUCT {
            let vertex_count = definitions
                .iter()
                .fold(0_usize, |maximum, &(left, right, _)| {
                    maximum.max(left).max(right)
                })
                + 1;
            let mut bns = make_graph(heap, vertex_count, definitions);
            {
                let stored_vertices = heap.slice_mut(bns.vert).unwrap();
                for vertex in stored_vertices.iter_mut().take(atom_limit) {
                    vertex.type_ = BNS_VERT_TYPE_ATOM as AT_NUMB;
                }
                for vertex in stored_vertices.iter_mut().skip(atom_limit) {
                    vertex.type_ = group_type;
                }
            }
            install_alt_path(heap, &mut bns, 0, vertices, 1);
            bns
        }

        fn make_aatg(heap: &mut SourceHeap, marks: &[S_CHAR], n_num_found: i32) -> BN_AATG {
            BN_AATG {
                nNumFound: n_num_found,
                nMarkedAtom: heap.allocate(marks.to_vec()).unwrap(),
                ..BN_AATG::default()
            }
        }

        let mut empty_heap = SourceHeap::default();
        let mut empty_bns = BN_STRUCT::default();
        let mut empty_aatg = make_aatg(&mut empty_heap, &[0, 0], 7);
        assert_eq!(
            MarkAtomsAtTautGroups(&mut empty_heap, &mut empty_bns, 2, &mut empty_aatg, -1, -1),
            Ok(7)
        );

        let definitions = [
            (4, 0, 0),
            (0, 1, 0),
            (1, 5, 0),
            (5, 2, 0),
            (2, 3, 0),
            (3, 6, 0),
        ];
        let path = [4, 0, 1, 5, 2, 3, 6];

        let mut success_heap = SourceHeap::default();
        let mut success_bns = make_markable_path(
            &mut success_heap,
            BNS_VERT_TYPE_TGROUP as AT_NUMB,
            &path,
            &definitions,
            4,
        );
        let mut success_aatg = make_aatg(&mut success_heap, &[0, 0, 0, 0], 99);
        assert_eq!(
            MarkAtomsAtTautGroups(
                &mut success_heap,
                &mut success_bns,
                4,
                &mut success_aatg,
                -1,
                -1
            ),
            Ok(4)
        );
        assert_eq!(success_aatg.nNumFound, 4);
        assert_eq!(
            success_heap
                .slice(success_aatg.nMarkedAtom.as_const())
                .unwrap(),
            &[AATG_MARK_IN_PATH as S_CHAR; 4]
        );
        assert_eq!(success_bns.alt_path, success_bns.altp[0]);

        let mut already_marked_heap = SourceHeap::default();
        let mut already_marked_bns = make_markable_path(
            &mut already_marked_heap,
            BNS_VERT_TYPE_TGROUP as AT_NUMB,
            &path,
            &definitions,
            4,
        );
        let mut already_marked_aatg = make_aatg(&mut already_marked_heap, &[1, 0, 0, 0], 77);
        assert_eq!(
            MarkAtomsAtTautGroups(
                &mut already_marked_heap,
                &mut already_marked_bns,
                4,
                &mut already_marked_aatg,
                -1,
                -1
            ),
            Ok(0)
        );
        assert_eq!(already_marked_aatg.nNumFound, 0);
        assert_eq!(
            already_marked_heap
                .slice(already_marked_aatg.nMarkedAtom.as_const())
                .unwrap(),
            &[1, 0, 0, 0]
        );

        let mut temp_heap = SourceHeap::default();
        let mut temp_bns = make_markable_path(
            &mut temp_heap,
            BNS_VERT_TYPE_TEMP as AT_NUMB,
            &path,
            &definitions,
            4,
        );
        let mut temp_aatg = make_aatg(&mut temp_heap, &[0, 0, 0, 0], 0);
        assert_eq!(
            MarkAtomsAtTautGroups(&mut temp_heap, &mut temp_bns, 4, &mut temp_aatg, -1, -1),
            Ok(4)
        );
        assert_eq!(
            temp_heap.slice(temp_aatg.nMarkedAtom.as_const()).unwrap(),
            &[AATG_MARK_IN_PATH as S_CHAR; 4]
        );

        let three_definitions = [(4, 0, 0), (0, 1, 0), (1, 5, 0), (5, 6, 0), (6, 2, 0)];
        let mut three_heap = SourceHeap::default();
        let mut three_bns = make_markable_path(
            &mut three_heap,
            BNS_VERT_TYPE_TGROUP as AT_NUMB,
            &[4, 0, 1, 5, 6, 2],
            &three_definitions,
            3,
        );
        let mut three_aatg = make_aatg(&mut three_heap, &[0, 0, 0], 12);
        assert_eq!(
            MarkAtomsAtTautGroups(&mut three_heap, &mut three_bns, 3, &mut three_aatg, -1, -1),
            Ok(0)
        );
        assert_eq!(
            three_heap.slice(three_aatg.nMarkedAtom.as_const()).unwrap(),
            &[0, 0, 0]
        );

        let mut wrong_end_heap = SourceHeap::default();
        let mut wrong_end_bns = make_markable_path(
            &mut wrong_end_heap,
            BNS_VERT_TYPE_TGROUP as AT_NUMB,
            &path,
            &definitions,
            4,
        );
        wrong_end_heap.slice_mut(wrong_end_bns.altp[0]).unwrap()
            [tagAltPathConst_iALTP_END_ATOM as usize]
            .set_number(99);
        let mut wrong_end_aatg = make_aatg(&mut wrong_end_heap, &[0, 0, 0, 0], 33);
        assert_eq!(
            MarkAtomsAtTautGroups(
                &mut wrong_end_heap,
                &mut wrong_end_bns,
                4,
                &mut wrong_end_aatg,
                -1,
                -1
            ),
            Ok(BNS_PROGRAM_ERR)
        );
        assert_eq!(wrong_end_aatg.nNumFound, 0);

        let endpoint_definitions = [(0, 1, 0)];
        let endpoint_path = [0, 1];
        let mut endpoint_heap = SourceHeap::default();
        let mut endpoint_bns = make_markable_path(
            &mut endpoint_heap,
            BNS_VERT_TYPE_TGROUP as AT_NUMB,
            &endpoint_path,
            &endpoint_definitions,
            2,
        );
        let mut endpoint_aatg = make_aatg(&mut endpoint_heap, &[0, 0], 44);
        assert_eq!(
            MarkAtomsAtTautGroups(
                &mut endpoint_heap,
                &mut endpoint_bns,
                2,
                &mut endpoint_aatg,
                0,
                -1
            ),
            Ok(0)
        );
        assert_eq!(endpoint_aatg.nNumFound, 0);

        let mut endpoint2_heap = SourceHeap::default();
        let mut endpoint2_bns = make_markable_path(
            &mut endpoint2_heap,
            BNS_VERT_TYPE_TGROUP as AT_NUMB,
            &endpoint_path,
            &endpoint_definitions,
            2,
        );
        let mut endpoint2_aatg = make_aatg(&mut endpoint2_heap, &[0, 0], 55);
        assert_eq!(
            MarkAtomsAtTautGroups(
                &mut endpoint2_heap,
                &mut endpoint2_bns,
                2,
                &mut endpoint2_aatg,
                1,
                -1
            ),
            Ok(0)
        );
        assert_eq!(endpoint2_aatg.nNumFound, 0);
    }

    #[test]
    fn source_port__ichi_bns__simpleremovehplusnpo__line_3432() {
        fn atom(
            element: u8,
            valence: i8,
            chem_bonds_valence: i8,
            num_h: i8,
            charge: i8,
            radical: i8,
        ) -> inp_ATOM {
            inp_ATOM {
                el_number: element,
                valence,
                chem_bonds_valence,
                num_H: num_h,
                charge,
                radical,
                at_type: 555,
                ..inp_ATOM::default()
            }
        }

        let mut atoms = vec![
            atom(7, 0, 0, 4, 1, 0),
            atom(8, 2, 2, 1, 1, 0),
            atom(6, 0, 0, 0, 0, 0),
            atom(6, 0, 0, 0, 0, 0),
        ];
        atoms[1].neighbor[..2].copy_from_slice(&[2, 3]);
        let mut totals = [0_i32; ATTOT_ARRAY_LEN];
        assert_eq!(mark_at_type(&mut atoms, 4, Some(&mut totals)), Ok(2));
        assert_eq!(totals[ATTOT_NUM_NP_PROTON], 1);
        assert_eq!(totals[ATTOT_NUM_OH_PLUS], 1);
        assert_eq!(totals[ATTOT_TOT_CHARGE], 2);
        assert_eq!(totals[ATTOT_NUM_CHARGES], 2);

        let mut groups = T_GROUP_INFO::default();
        assert_eq!(
            SimpleRemoveHplusNPO(&mut atoms, 4, Some(&mut totals), &mut groups),
            Ok(2)
        );
        assert_eq!((atoms[0].charge, atoms[0].num_H), (0, 3));
        assert_eq!((atoms[1].charge, atoms[1].num_H), (0, 0));
        assert_eq!((atoms[2].charge, atoms[2].num_H), (0, 0));
        assert_eq!((atoms[3].charge, atoms[3].num_H), (0, 0));
        assert_eq!(groups.tni.nNumRemovedProtons, 2);
        assert_eq!(totals[ATTOT_NUM_NP_PROTON], 0);
        assert_eq!(totals[ATTOT_NUM_NP_H], 1);
        assert_eq!(totals[ATTOT_NUM_OH_PLUS], 0);
        assert_eq!(totals[ATTOT_TOT_CHARGE], 0);
        assert_eq!(totals[ATTOT_NUM_CHARGES], 0);

        let mut without_totals = vec![atom(15, 0, 0, 4, 1, 0), atom(6, 0, 0, 0, 0, 0)];
        let mut without_totals_groups = T_GROUP_INFO::default();
        assert_eq!(
            SimpleRemoveHplusNPO(&mut without_totals, 2, None, &mut without_totals_groups),
            Ok(1)
        );
        assert_eq!((without_totals[0].charge, without_totals[0].num_H), (0, 3));
        assert_eq!((without_totals[1].charge, without_totals[1].num_H), (0, 0));
        assert_eq!(without_totals_groups.tni.nNumRemovedProtons, 1);

        let mut negative_count = vec![atom(7, 0, 0, 4, 1, 0)];
        let mut negative_groups = T_GROUP_INFO::default();
        assert_eq!(
            SimpleRemoveHplusNPO(&mut negative_count, -1, None, &mut negative_groups),
            Ok(0)
        );
        assert_eq!((negative_count[0].charge, negative_count[0].num_H), (1, 4));
        assert_eq!(negative_groups.tni.nNumRemovedProtons, 0);

        let mut too_few_atoms = vec![atom(7, 0, 0, 4, 1, 0)];
        let mut too_few_groups = T_GROUP_INFO::default();
        assert_eq!(
            SimpleRemoveHplusNPO(&mut too_few_atoms, 2, None, &mut too_few_groups),
            Err(SourceHeapError::PointerOutOfBounds)
        );
    }

    #[test]
    fn source_port__ichi_bns__simpleremoveacidicprotons__line_4129() {
        fn atom(
            element: u8,
            valence: i8,
            chem_bonds_valence: i8,
            num_h: i8,
            charge: i8,
            radical: i8,
        ) -> inp_ATOM {
            inp_ATOM {
                el_number: element,
                valence,
                chem_bonds_valence,
                num_H: num_h,
                charge,
                radical,
                at_type: 555,
                ..inp_ATOM::default()
            }
        }

        fn acidic_co_atoms() -> Vec<inp_ATOM> {
            let mut atoms = vec![atom(8, 1, 1, 1, 0, 0), atom(6, 1, 4, 0, 0, 0)];
            atoms[0].neighbor[0] = 1;
            atoms[1].neighbor[0] = 0;
            atoms
        }

        fn make_aatg(heap: &mut SourceHeap) -> BN_AATG {
            BN_AATG {
                nAtTypeTotals: heap.allocate(vec![0_i32; ATTOT_ARRAY_LEN]).unwrap(),
                t_group_info: heap.allocate(vec![T_GROUP_INFO::default()]).unwrap(),
                ..BN_AATG::default()
            }
        }

        let mut no_candidate_heap = SourceHeap::default();
        let mut no_candidate_atoms = vec![atom(6, 0, 0, 0, 0, 0)];
        assert_eq!(
            SimpleRemoveAcidicProtons(
                &mut no_candidate_heap,
                &mut no_candidate_atoms,
                1,
                &BN_AATG::default(),
                1,
            ),
            Ok(0)
        );
        assert_eq!(
            (no_candidate_atoms[0].charge, no_candidate_atoms[0].num_H),
            (0, 0)
        );

        let mut zero_heap = SourceHeap::default();
        let mut zero_atoms = acidic_co_atoms();
        assert_eq!(
            SimpleRemoveAcidicProtons(&mut zero_heap, &mut zero_atoms, 2, &BN_AATG::default(), 0,),
            Ok(0)
        );
        assert_eq!((zero_atoms[0].charge, zero_atoms[0].num_H), (0, 1));

        let mut heap = SourceHeap::default();
        let mut atoms = acidic_co_atoms();
        let aatg = make_aatg(&mut heap);
        {
            let totals = heap.slice_mut(aatg.nAtTypeTotals).unwrap();
            assert_eq!(mark_at_type(&mut atoms, 2, Some(totals)), Ok(0));
        }
        assert_eq!(
            heap.slice(aatg.nAtTypeTotals.as_const()).unwrap()[ATTOT_NUM_COH],
            1
        );

        assert_eq!(
            SimpleRemoveAcidicProtons(&mut heap, &mut atoms, 2, &aatg, 1),
            Ok(1)
        );
        assert_eq!((atoms[0].charge, atoms[0].num_H), (-1, 0));
        assert_eq!((atoms[1].charge, atoms[1].num_H), (0, 0));
        let totals = heap.slice(aatg.nAtTypeTotals.as_const()).unwrap();
        assert_eq!(totals[ATTOT_NUM_COH], 0);
        assert_eq!(totals[ATTOT_NUM_CO_MINUS], 1);
        assert_eq!(totals[ATTOT_TOT_CHARGE], -1);
        assert_eq!(totals[ATTOT_NUM_CHARGES], 1);
        let group_info = heap.slice(aatg.t_group_info.as_const()).unwrap();
        assert_eq!(group_info[0].tni.nNumRemovedProtons, 1);

        let mut missing_heap = SourceHeap::default();
        let mut missing_atoms = acidic_co_atoms();
        assert_eq!(
            SimpleRemoveAcidicProtons(
                &mut missing_heap,
                &mut missing_atoms,
                2,
                &BN_AATG::default(),
                1,
            ),
            Err(SourceHeapError::NullPointer)
        );
        assert_eq!((missing_atoms[0].charge, missing_atoms[0].num_H), (0, 1));
    }

    #[test]
    fn source_port__ichi_bns__bhasacidichydrogen__line_4200() {
        fn atom(
            element: u8,
            valence: i8,
            chem_bonds_valence: i8,
            num_h: i8,
            charge: i8,
        ) -> inp_ATOM {
            inp_ATOM {
                el_number: element,
                valence,
                chem_bonds_valence,
                num_H: num_h,
                charge,
                ..inp_ATOM::default()
            }
        }

        let mut acidic_co = vec![atom(8, 1, 1, 1, 0), atom(6, 1, 4, 0, 0)];
        acidic_co[0].neighbor[0] = 1;
        acidic_co[1].neighbor[0] = 0;
        assert_eq!(bHasAcidicHydrogen(&acidic_co, 0), Ok(1));

        let hydrochloric_acid = vec![atom(17, 0, 0, 1, 0)];
        assert_eq!(bHasAcidicHydrogen(&hydrochloric_acid, 0), Ok(1));

        let mut charged = acidic_co.clone();
        charged[0].charge = -1;
        assert_eq!(bHasAcidicHydrogen(&charged, 0), Ok(0));

        let mut no_hydrogen = acidic_co.clone();
        no_hydrogen[0].num_H = 0;
        assert_eq!(bHasAcidicHydrogen(&no_hydrogen, 0), Ok(0));

        let carbon_hydrogen = vec![atom(6, 0, 0, 1, 0)];
        assert_eq!(bHasAcidicHydrogen(&carbon_hydrogen, 0), Ok(0));
        assert_eq!(
            bHasAcidicHydrogen(&carbon_hydrogen, -1),
            Err(SourceHeapError::PointerOutOfBounds)
        );
        assert_eq!(
            bHasAcidicHydrogen(&carbon_hydrogen, 1),
            Err(SourceHeapError::PointerOutOfBounds)
        );
    }

    #[test]
    fn source_port__ichi_bns__bhasotherexchangableh__line_4220() {
        let exchangeable_n = inp_ATOM {
            el_number: 7,
            valence: 0,
            chem_bonds_valence: 2,
            num_H: 1,
            ..inp_ATOM::default()
        };
        assert_eq!(bHasOtherExchangableH(&[exchangeable_n.clone()], 0), Ok(1));

        let mut no_hydrogen = exchangeable_n.clone();
        no_hydrogen.num_H = 0;
        assert_eq!(bHasOtherExchangableH(&[no_hydrogen], 0), Ok(0));

        let oxygen = inp_ATOM {
            el_number: 8,
            valence: 1,
            chem_bonds_valence: 1,
            num_H: 1,
            ..inp_ATOM::default()
        };
        assert_eq!(bHasOtherExchangableH(&[oxygen], 0), Ok(0));

        let nonmatching_n = inp_ATOM {
            el_number: 7,
            valence: 0,
            chem_bonds_valence: 3,
            num_H: 1,
            charge: 1,
            ..inp_ATOM::default()
        };
        assert_eq!(bHasOtherExchangableH(&[nonmatching_n], 0), Ok(0));

        let atoms = [exchangeable_n];
        assert_eq!(
            bHasOtherExchangableH(&atoms, -1),
            Err(SourceHeapError::PointerOutOfBounds)
        );
        assert_eq!(
            bHasOtherExchangableH(&atoms, 1),
            Err(SourceHeapError::PointerOutOfBounds)
        );
    }

