    #[test]
    fn source_port__ichi_bns__simpleaddacidicprotons__line_4253() {
        fn atom(
            element: u8,
            valence: i8,
            chem_bonds_valence: i8,
            num_h: i8,
            charge: i8,
            radical: i8,
        ) -> inp_ATOM {
            inp_ATOM {
                el_number: element,
                valence,
                chem_bonds_valence,
                num_H: num_h,
                charge,
                radical,
                at_type: 555,
                ..inp_ATOM::default()
            }
        }

        fn acidic_minus_atoms() -> Vec<inp_ATOM> {
            let mut atoms = vec![atom(8, 1, 1, 0, -1, 0), atom(6, 1, 4, 0, 0, 0)];
            atoms[0].neighbor[0] = 1;
            atoms[1].neighbor[0] = 0;
            atoms
        }

        fn n_minus_atoms() -> Vec<inp_ATOM> {
            let mut atoms = vec![atom(7, 1, 2, 0, -1, 0), atom(6, 1, 4, 0, 0, 0)];
            atoms[0].neighbor[0] = 1;
            atoms[0].bond_type[0] = BOND_MARK_ALL as u8;
            atoms[1].neighbor[0] = 0;
            atoms
        }

        fn make_aatg(heap: &mut SourceHeap) -> BN_AATG {
            BN_AATG {
                nAtTypeTotals: heap.allocate(vec![0_i32; ATTOT_ARRAY_LEN]).unwrap(),
                t_group_info: heap.allocate(vec![T_GROUP_INFO::default()]).unwrap(),
                ..BN_AATG::default()
            }
        }

        let mut no_candidate_heap = SourceHeap::default();
        let mut no_candidate_atoms = vec![atom(6, 0, 0, 0, 0, 0)];
        assert_eq!(
            SimpleAddAcidicProtons(
                &mut no_candidate_heap,
                &mut no_candidate_atoms,
                1,
                &BN_AATG::default(),
                1,
            ),
            Ok(0)
        );
        assert_eq!(
            (no_candidate_atoms[0].charge, no_candidate_atoms[0].num_H),
            (0, 0)
        );

        let mut zero_heap = SourceHeap::default();
        let mut zero_atoms = acidic_minus_atoms();
        assert_eq!(
            SimpleAddAcidicProtons(&mut zero_heap, &mut zero_atoms, 2, &BN_AATG::default(), 0,),
            Ok(0)
        );
        assert_eq!((zero_atoms[0].charge, zero_atoms[0].num_H), (-1, 0));

        let mut heap = SourceHeap::default();
        let mut atoms = acidic_minus_atoms();
        let aatg = make_aatg(&mut heap);
        {
            let totals = heap.slice_mut(aatg.nAtTypeTotals).unwrap();
            assert_eq!(mark_at_type(&mut atoms, 2, Some(totals)), Ok(1));
        }
        assert_eq!(
            SimpleAddAcidicProtons(&mut heap, &mut atoms, 2, &aatg, 1),
            Ok(1)
        );
        assert_eq!((atoms[0].charge, atoms[0].num_H), (0, 1));
        assert_eq!((atoms[1].charge, atoms[1].num_H), (0, 0));
        let totals = heap.slice(aatg.nAtTypeTotals.as_const()).unwrap();
        assert_eq!(totals[ATTOT_NUM_CO_MINUS], 0);
        assert_eq!(totals[ATTOT_NUM_COH], 1);
        assert_eq!(totals[ATTOT_TOT_CHARGE], 0);
        assert_eq!(totals[ATTOT_NUM_CHARGES], 0);
        let group_info = heap.slice(aatg.t_group_info.as_const()).unwrap();
        assert_eq!(group_info[0].tni.nNumRemovedProtons, -1);

        let mut n_heap = SourceHeap::default();
        let mut n_atoms = n_minus_atoms();
        let n_aatg = make_aatg(&mut n_heap);
        {
            let totals = n_heap.slice_mut(n_aatg.nAtTypeTotals).unwrap();
            assert_eq!(mark_at_type(&mut n_atoms, 2, Some(totals)), Ok(1));
        }
        assert_eq!(
            SimpleAddAcidicProtons(&mut n_heap, &mut n_atoms, 2, &n_aatg, 1),
            Ok(1)
        );
        assert_eq!((n_atoms[0].charge, n_atoms[0].num_H), (0, 1));
        let n_totals = n_heap.slice(n_aatg.nAtTypeTotals.as_const()).unwrap();
        assert_eq!(n_totals[ATTOT_NUM_N_MINUS], 0);
        assert_eq!(n_totals[ATTOT_NUM_NP_H], 1);

        let mut missing_heap = SourceHeap::default();
        let mut missing_atoms = acidic_minus_atoms();
        assert_eq!(
            SimpleAddAcidicProtons(
                &mut missing_heap,
                &mut missing_atoms,
                2,
                &BN_AATG::default(),
                1,
            ),
            Err(SourceHeapError::NullPointer)
        );
        assert_eq!((missing_atoms[0].charge, missing_atoms[0].num_H), (-1, 0));
    }

