            assert_eq!(edges[0].neighbor12, 1);
            assert_eq!(edges[0].neigh_ord, [0, 0]);
            assert_eq!((edges[0].cap, edges[0].flow), (1, 0));
            assert_eq!((edges[0].cap0, edges[0].flow0), (1, 0));
