            assert_eq!(edges[1].neighbor12, 2);
            assert_eq!(edges[1].neigh_ord, [1, 0]);
            assert_eq!((edges[1].cap, edges[1].flow), (1, 1));
            assert_eq!((edges[1].cap0, edges[1].flow0), (1, 1));
