            assert_eq!(vertices[0].st_edge.cap0, 4);
            assert_eq!(vertices[0].st_edge.flow, 2);
            assert_eq!(vertices[0].st_edge.flow0, 2);
            assert_eq!(vertices[0].type_, 0);
            assert_eq!(vertices[0].num_adj_edges, 0);
            assert_eq!(vertices[1].st_edge.cap, 5);
            assert_eq!(vertices[1].st_edge.cap0, 5);
            assert_eq!(vertices[1].st_edge.flow, 2);
            assert_eq!(vertices[1].st_edge.flow0, 2);
            assert_eq!(vertices[1].type_, BNS_VERT_TYPE_C_POINT as AT_NUMB);
            assert_eq!(vertices[1].num_adj_edges, 0);
