    #[test]
    fn source_port__ichi_bns__setatombondtype__line_480() {
        fn run(
            flow0: i32,
            flow: i32,
            pass: i8,
            first: u8,
            second: u8,
            delta: i32,
            flags: u32,
        ) -> (i32, u8, u8) {
            let edge = BNS_EDGE {
                flow0,
                flow,
                pass,
                ..BNS_EDGE::default()
            };
            let mut left = first;
            let mut right = second;
            let result = SetAtomBondType(&edge, &mut left, Some(&mut right), delta, flags as i32);
            (result, left, right)
        }

        assert_eq!(
            run(0, 2, 0, BOND_SINGLE as u8, 99, 2, BNS_EF_CHNG_BONDS),
            (0, BOND_SINGLE as u8, 99)
        );
        let edge = BNS_EDGE {
            pass: 1,
            flow0: 0,
            ..BNS_EDGE::default()
        };
        let mut only = BOND_SINGLE as u8;
        assert_eq!(
            SetAtomBondType(&edge, &mut only, None, 1, BNS_EF_CHNG_BONDS as i32),
            0
        );
        assert_eq!(only, BOND_SINGLE as u8);

        assert_eq!(
            run(0, 2, 1, BOND_SINGLE as u8, 77, 2, BNS_EF_CHNG_BONDS),
            (1, BOND_TRIPLE as u8, BOND_TRIPLE as u8)
        );
        assert_eq!(
            run(
                0,
                1,
                1,
                BOND_SINGLE as u8,
                77,
                9,
                BNS_EF_CHNG_FLOW | BNS_EF_CHNG_BONDS,
            ),
            (1, BOND_DOUBLE as u8, BOND_DOUBLE as u8)
        );
        assert_eq!(
            run(1, 1, 1, BOND_DOUBLE as u8, 77, 0, BNS_EF_CHNG_BONDS),
            (0, BOND_DOUBLE as u8, 77)
        );

        let alternating = [
            (
                0,
                1,
                BOND_SINGLE,
                BNS_EF_ALTR_BONDS,
                BOND_ALTERN | BOND_MARK_ALT12,
            ),
            (
                1,
                0,
                BOND_DOUBLE,
                BNS_EF_ALTR_BONDS | BNS_EF_SET_NOSTEREO,
                BOND_ALT12NS | BOND_MARK_ALT12NS,
            ),
            (
                0,
                2,
                BOND_TRIPLE,
                BNS_EF_ALTR_BONDS,
                BOND_ALT_13 | BOND_MARK_ALT13,
            ),
            (
                2,
                1,
                BOND_SINGLE,
                BNS_EF_ALTR_BONDS,
                BOND_ALT_23 | BOND_MARK_ALT23,
            ),
            (
                0,
                1,
                BOND_TAUTOM,
                BNS_EF_ALTR_BONDS,
                BOND_TAUTOM | BOND_MARK_ALT12NS,
            ),
            (
                1,
                2,
                BOND_TAUTOM,
                BNS_EF_ALTR_BONDS,
                BOND_TAUTOM | BOND_MARK_ALT23,
            ),
        ];
        for (flow0, flow, initial, flags, expected) in alternating {
            assert_eq!(
                run(flow0, flow, 1, initial as u8, 91, flow - flow0, flags),
                (1, expected as u8, expected as u8)
            );
        }

        assert_eq!(
            run(0, 3, 1, BOND_SINGLE as u8, 88, 3, BNS_EF_ALTR_BONDS),
            (BNS_BOND_ERR, BOND_SINGLE as u8, 88)
        );
        assert_eq!(
            run(0, 2, 1, BOND_TAUTOM as u8, 88, 2, BNS_EF_ALTR_BONDS),
            (BNS_BOND_ERR, BOND_TAUTOM as u8, 88)
        );

        let marked = [
            (
                0,
                1,
                BOND_ALTERN | BOND_MARK_ALT12,
                BNS_EF_ALTR_BONDS | BNS_EF_SET_NOSTEREO,
                BOND_ALT12NS | BOND_MARK_ALT12NS,
            ),
            (
                1,
                2,
                BOND_ALTERN | BOND_MARK_ALT12,
                BNS_EF_ALTR_BONDS,
                BOND_ALT_123 | BOND_MARK_ALT123,
            ),
            (
                0,
                2,
                BOND_ALT12NS | BOND_MARK_ALT12NS,
                BNS_EF_ALTR_BONDS,
                BOND_ALT_123 | BOND_MARK_ALT123,
            ),
            (
                1,
                2,
                BOND_ALT_13 | BOND_MARK_ALT13,
                BNS_EF_ALTR_BONDS,
                BOND_ALT_123 | BOND_MARK_ALT123,
            ),
            (
                0,
                1,
                BOND_ALT_23 | BOND_MARK_ALT23,
                BNS_EF_ALTR_BONDS,
                BOND_ALT_123 | BOND_MARK_ALT123,
            ),
            (
                0,
                1,
                BOND_ALT_123 | BOND_MARK_ALT123,
                BNS_EF_ALTR_BONDS,
                BOND_ALT_123 | BOND_MARK_ALT123,
            ),
            (
                0,
                1,
                BOND_ALTERN,
                BNS_EF_ALTR_BONDS,
                BOND_ALTERN | BOND_MARK_ALT12,
            ),
            (
                0,
                2,
                BOND_ALT_13,
                BNS_EF_ALTR_BONDS,
                BOND_ALT_13 | BOND_MARK_ALT13,
            ),
            (
                1,
                2,
                BOND_ALT_23,
                BNS_EF_ALTR_BONDS,
                BOND_ALT_23 | BOND_MARK_ALT23,
            ),
        ];
        for (flow0, flow, initial, flags, expected) in marked {
            let expected_change = i32::from(initial != expected);
            assert_eq!(
                run(flow0, flow, 1, initial as u8, 19, flow - flow0, flags),
                (
                    expected_change,
                    expected as u8,
                    if expected_change != 0 {
                        expected as u8
                    } else {
                        19
                    }
                )
            );
        }

        assert_eq!(
            run(
                0,
                1,
                1,
                (BOND_ALTERN | 0x60) as u8,
                44,
                1,
                BNS_EF_ALTR_BONDS,
            ),
            (BNS_BOND_ERR, (BOND_ALTERN | 0x60) as u8, 44)
        );
        assert_eq!(
            run(0, 1, 1, 15, 44, 1, BNS_EF_ALTR_BONDS),
            (BNS_BOND_ERR, 15, 44)
        );
        assert_eq!(
            run(0, 0, 1, BOND_ALTERN as u8, 44, 0, BNS_EF_ALTR_BONDS),
            (0, BOND_ALTERN as u8, 44)
        );
    }

