    #[test]
    fn source_port__ichi_bns__brestoreflowaftercheckonebond__line_6180() {
        let mut heap = SourceHeap::default();
        let mut bns = make_graph(
            &mut heap,
            3,
            &[(0, 1, BOND_SINGLE as i8), (1, 2, BOND_SINGLE as i8)],
        );
        {
            let edges = heap.slice_mut(bns.edge).unwrap();
            edges[0].flow = 99;
            edges[0].cap = 88;
            edges[0].pass = 1;
            edges[1].flow = 77;
            edges[1].cap = 66;
            edges[1].pass = 1;
        }
        {
            let vertices = heap.slice_mut(bns.vert).unwrap();
            for vertex in vertices {
                vertex.st_edge.flow = 55;
                vertex.st_edge.cap = 44;
                vertex.st_edge.pass = 1;
            }
        }
        let fcd = heap
            .allocate(vec![
                BNS_FLOW_CHANGES {
                    iedge: 0,
                    flow: 1,
                    cap: 2,
                    v1: 1,
                    flow_st1: 3,
                    cap_st1: 4,
                    v2: NO_VERTEX,
                    ..BNS_FLOW_CHANGES::default()
                },
                BNS_FLOW_CHANGES {
                    iedge: 1,
                    flow: 5,
                    cap: 6,
                    v1: 1,
                    flow_st1: 7,
                    cap_st1: 8,
                    v2: 2,
                    flow_st2: 9,
                    cap_st2: 10,
                    ..BNS_FLOW_CHANGES::default()
                },
                BNS_FLOW_CHANGES {
                    iedge: NO_VERTEX,
                    ..BNS_FLOW_CHANGES::default()
                },
            ])
            .unwrap();

        assert_eq!(
            bRestoreFlowAfterCheckOneBond(&mut heap, &mut bns, fcd),
            Ok(0)
        );
        let edges = heap.slice(bns.edge.as_const()).unwrap();
        assert_eq!((edges[0].flow, edges[0].cap, edges[0].pass), (1, 2, 0));
        assert_eq!((edges[1].flow, edges[1].cap, edges[1].pass), (5, 6, 0));
        let vertices = heap.slice(bns.vert.as_const()).unwrap();
        assert_eq!(
            (
                vertices[1].st_edge.flow,
                vertices[1].st_edge.cap,
                vertices[1].st_edge.pass,
            ),
            (3, 4, 0)
        );
        assert_eq!(
            (
                vertices[2].st_edge.flow,
                vertices[2].st_edge.cap,
                vertices[2].st_edge.pass,
            ),
            (9, 10, 0)
        );
    }

