    #[test]
    fn source_port__ichi_bns__restorebnstructflow__line_1525() {
        fn fixture() -> (SourceHeap, BN_STRUCT, SourceMutPointer<BNS_ALT_PATH>) {
            let mut heap = SourceHeap::default();
            let mut bns = make_graph(&mut heap, 2, &[(0, 1, 1)]);
            let path = install_alt_path(&mut heap, &mut bns, 0, &[0, 1], 2);
            {
                let vertices = heap.slice_mut(bns.vert).unwrap();
                vertices[0].st_edge.flow0 = 1;
                vertices[0].st_edge.flow = 5;
                vertices[1].st_edge.flow0 = 2;
                vertices[1].st_edge.flow = 7;
            }
            {
                let edge = &mut heap.slice_mut(bns.edge).unwrap()[0];
                edge.flow0 = 3;
                edge.flow = 9;
                edge.pass = 1;
            }
            (heap, bns, path)
        }

        let mut empty_heap = SourceHeap::default();
        let mut empty_bns = make_graph(&mut empty_heap, 1, &[]);
        assert_eq!(
            RestoreBnStructFlow(&mut empty_heap, &mut empty_bns, BNS_EF_SAVE_ALL as i32),
            Ok(0)
        );

        let (mut save_heap, mut save_bns, save_path) = fixture();
        assert_eq!(
            RestoreBnStructFlow(&mut save_heap, &mut save_bns, BNS_EF_SAVE_ALL as i32,),
            Ok(0)
        );
        let save_vertices = save_heap.slice(save_bns.vert.as_const()).unwrap();
        assert_eq!(
            (
                save_vertices[0].st_edge.flow0,
                save_vertices[0].st_edge.flow,
                save_vertices[1].st_edge.flow0,
                save_vertices[1].st_edge.flow,
            ),
            (5, 5, 7, 7)
        );
        let save_edge = &save_heap.slice(save_bns.edge.as_const()).unwrap()[0];
        assert_eq!((save_edge.flow0, save_edge.flow, save_edge.pass), (9, 9, 0));
        assert_eq!(save_bns.alt_path, save_path);

        let (mut restore_heap, mut restore_bns, _) = fixture();
        assert_eq!(
            RestoreBnStructFlow(&mut restore_heap, &mut restore_bns, BNS_EF_CHNG_RSTR as i32,),
            Ok(0)
        );
        let restore_vertices = restore_heap.slice(restore_bns.vert.as_const()).unwrap();
        assert_eq!(
            (
                restore_vertices[0].st_edge.flow0,
                restore_vertices[0].st_edge.flow,
                restore_vertices[1].st_edge.flow0,
                restore_vertices[1].st_edge.flow,
            ),
            (1, 3, 2, 5)
        );
        let restore_edge = &restore_heap.slice(restore_bns.edge.as_const()).unwrap()[0];
        assert_eq!(
            (restore_edge.flow0, restore_edge.flow, restore_edge.pass),
            (3, 7, 0)
        );

        let (mut mismatch_heap, mut mismatch_bns, mismatch_path) = fixture();
        mismatch_heap.slice_mut(mismatch_path).unwrap()[4].set_number(0);
        assert_eq!(
            RestoreBnStructFlow(
                &mut mismatch_heap,
                &mut mismatch_bns,
                BNS_EF_SAVE_ALL as i32,
            ),
            Ok(BNS_PROGRAM_ERR)
        );
        let mismatch_vertices = mismatch_heap.slice(mismatch_bns.vert.as_const()).unwrap();
        assert_eq!(mismatch_vertices[0].st_edge.flow0, 5);
        assert_eq!(mismatch_vertices[1].st_edge.flow0, 2);
        assert_eq!(
            mismatch_heap.slice(mismatch_bns.edge.as_const()).unwrap()[0].flow0,
            9
        );
    }

    #[test]
    fn source_port__ichi_bns__setatomradandchemvalfromvertexcapflow__line_726() {
        fn run(
            valence: i8,
            chem_bonds_valence: i8,
            radical: i8,
            pass: i8,
            cap: i32,
            flow: i32,
        ) -> (Result<i32, SourceHeapError>, inp_ATOM) {
            let mut heap = SourceHeap::default();
            let mut bns = make_graph(&mut heap, 1, &[]);
            heap.slice_mut(bns.vert).unwrap()[0].st_edge = crate::source_types::BNS_ST_EDGE {
                pass,
                cap,
                flow,
                ..crate::source_types::BNS_ST_EDGE::default()
            };
            let atoms = heap
                .allocate(vec![inp_ATOM {
                    valence,
                    chem_bonds_valence,
                    radical,
                    ..inp_ATOM::default()
                }])
                .unwrap();
            let result = SetAtomRadAndChemValFromVertexCapFlow(&mut heap, &bns, atoms, 0);
            (result, heap.slice(atoms.as_const()).unwrap()[0].clone())
        }

        let (result, atom) = run(3, 7, 9, 0, 2, 2);
        assert_eq!(result, Ok(0));
        assert_eq!(
            (atom.valence, atom.chem_bonds_valence, atom.radical),
            (3, 7, 9)
        );

        let (result, atom) = run(3, 4, 9, 1, 3, 2);
        assert_eq!(result, Ok(2));
        assert_eq!(
            (atom.chem_bonds_valence, atom.radical),
            (5, RADICAL_DOUBLET as i8)
        );

        let (result, atom) = run(3, 2, 0, 1, 4, 2);
        assert_eq!(result, Ok(1));
        assert_eq!(
            (atom.chem_bonds_valence, atom.radical),
            (2, RADICAL_TRIPLET as i8)
        );

        let (result, atom) = run(3, 5, 0, 1, 4, 1);
        assert_eq!(result, Ok(BNS_BOND_ERR));
        assert_eq!((atom.chem_bonds_valence, atom.radical), (4, 0));

        let mut heap = SourceHeap::default();
        let bns = make_graph(&mut heap, 1, &[]);
        let atoms = heap.allocate(vec![inp_ATOM::default()]).unwrap();
        assert_eq!(
            SetAtomRadAndChemValFromVertexCapFlow(&mut heap, &bns, atoms, -1),
            Err(SourceHeapError::PointerOutOfBounds)
        );
    }

