    #[test]
    fn source_port__ichi_bns__nmaxflow2check__line_6010() {
        let mut heap = SourceHeap::default();
        let mut edges = vec![BNS_EDGE::default(); 6];
        for (edge, cap) in edges.iter_mut().zip([
            0_i32,
            1,
            MAX_BOND_EDGE_CAP as i32,
            MAX_BOND_EDGE_CAP as i32 + 1,
            EDGE_FLOW_MASK as i32,
            -1,
        ]) {
            edge.cap = cap;
        }
        let mut bns = BN_STRUCT {
            edge: heap.allocate(edges).unwrap(),
            ..BN_STRUCT::default()
        };

        assert_eq!(nMaxFlow2Check(&heap, &bns, 0), Ok(0));
        assert_eq!(nMaxFlow2Check(&heap, &bns, 1), Ok(1));
        assert_eq!(nMaxFlow2Check(&heap, &bns, 2), Ok(MAX_BOND_EDGE_CAP as i32));
        assert_eq!(nMaxFlow2Check(&heap, &bns, 3), Ok(MAX_BOND_EDGE_CAP as i32));
        assert_eq!(nMaxFlow2Check(&heap, &bns, 4), Ok(MAX_BOND_EDGE_CAP as i32));
        assert_eq!(nMaxFlow2Check(&heap, &bns, 5), Ok(MAX_BOND_EDGE_CAP as i32));

        assert_eq!(
            nMaxFlow2Check(&heap, &bns, -1),
            Err(SourceHeapError::PointerOutOfBounds)
        );
        bns.edge = SourceMutPointer::null();
        assert_eq!(
            nMaxFlow2Check(&heap, &bns, 0),
            Err(SourceHeapError::NullPointer)
        );
    }

