    #[test]
    fn source_port__ichi_bns__nbondsvalenceinpat__line_1673() {
        fn run(bonds: &[u8]) -> (i32, i32, i32) {
            let mut atom = inp_ATOM {
                valence: bonds.len() as i8,
                ..inp_ATOM::default()
            };
            atom.bond_type[..bonds.len()].copy_from_slice(bonds);
            let mut altern = -1;
            let mut wrong = -1;
            let valence = nBondsValenceInpAt(&atom, Some(&mut altern), Some(&mut wrong));
            (valence, altern, wrong)
        }

        assert_eq!(run(&[]), (0, 0, 0));
        assert_eq!(
            run(&[0, BOND_SINGLE as u8, BOND_DOUBLE as u8, BOND_TRIPLE as u8,]),
            (6, 0, 0)
        );
        assert_eq!(run(&[BOND_ALTERN as u8]), (1, 1, 1));
        assert_eq!(run(&[BOND_ALTERN as u8, BOND_ALTERN as u8]), (3, 2, 0));
        assert_eq!(
            run(&[
                BOND_ALTERN as u8,
                BOND_ALTERN as u8,
                BOND_ALTERN as u8,
                BOND_DOUBLE as u8,
            ]),
            (6, 3, 0)
        );
        assert_eq!(run(&[BOND_ALT_123 as u8, BOND_ALT12NS as u8]), (0, 0, 2));
        assert_eq!(
            run(&[
                (BOND_SINGLE | 0xf0) as u8,
                (BOND_ALTERN | 0xa0) as u8,
                (BOND_ALT_13 | 0x50) as u8,
            ]),
            (2, 1, 2)
        );

        let mut negative = inp_ATOM {
            valence: -1,
            ..inp_ATOM::default()
        };
        negative.bond_type[0] = BOND_TRIPLE as u8;
        let mut altern = 71;
        assert_eq!(nBondsValenceInpAt(&negative, Some(&mut altern), None), 0);
        assert_eq!(altern, 0);

        let mut ignored_outputs = inp_ATOM {
            valence: 1,
            ..inp_ATOM::default()
        };
        ignored_outputs.bond_type[0] = BOND_ALTERN as u8;
        assert_eq!(nBondsValenceInpAt(&ignored_outputs, None, None), 1);

        let mut bounded = inp_ATOM {
            valence: 1,
            ..inp_ATOM::default()
        };
        bounded.bond_type[0] = BOND_SINGLE as u8;
        bounded.bond_type[1] = BOND_TRIPLE as u8;
        assert_eq!(nBondsValenceInpAt(&bounded, None, None), 1);
    }

