    #[test]
    fn source_port__ichi_bns__getprevvertex__line_10163() {
        let mut heap = SourceHeap::default();
        let mut bns = make_graph(&mut heap, 3, &[(0, 2, 0)]);
        heap.slice_mut(bns.edge).unwrap()[0].cap = 1;

        let mut direct_edges = vec![[NO_VERTEX, -1]; 4];
        direct_edges[2] = [0, -3];
        let direct_edges = heap.allocate(direct_edges).unwrap();
        let mut iuv = 91;
        assert_eq!(GetPrevVertex(&heap, &bns, 2, direct_edges, &mut iuv), Ok(0));
        assert_eq!(iuv, -3);

        let mut chain = vec![[NO_VERTEX, -1]; 10];
        chain[2] = [4, 0];
        chain[8] = [3, -2];
        let chain = heap.allocate(chain).unwrap();
        iuv = 91;
        assert_eq!(GetPrevVertex(&heap, &bns, 2, chain, &mut iuv), Ok(1));
        assert_eq!(iuv, -2);

        heap.slice_mut(chain).unwrap()[8] = [3, 0];
        iuv = 91;
        assert_eq!(GetPrevVertex(&heap, &bns, 2, chain, &mut iuv), Ok(7));
        assert_eq!(iuv, 0);

        heap.slice_mut(chain).unwrap()[8] = [8, -2];
        iuv = 91;
        assert_eq!(
            GetPrevVertex(&heap, &bns, 2, chain, &mut iuv),
            Ok(NO_VERTEX)
        );
        assert_eq!(iuv, 91);

        heap.slice_mut(chain).unwrap()[8] = [NO_VERTEX, -2];
        assert_eq!(
            GetPrevVertex(&heap, &bns, 2, chain, &mut iuv),
            Ok(NO_VERTEX)
        );
        assert_eq!(iuv, 91);

        assert_eq!(
            GetPrevVertex(&heap, &bns, 2, SourceMutPointer::null(), &mut iuv,),
            Err(SourceHeapError::NullPointer)
        );

        bns.edge = SourceMutPointer::null();
        assert_eq!(
            GetPrevVertex(&heap, &bns, 2, chain, &mut iuv),
            Err(SourceHeapError::NullPointer)
        );
    }

    #[test]
    fn source_port__ichi_bns__bignorevertexnontacn_group__line_10419() {
        const TYPE_TACN: AT_NUMB = 1;
        const TYPE_T: AT_NUMB = 2;
        const TYPE_CN: AT_NUMB = 4;

        let no_vertices = BN_STRUCT {
            type_TACN: TYPE_TACN,
            ..BN_STRUCT::default()
        };
        assert_eq!(
            bIgnoreVertexNonTACN_group(
                &SourceHeap::default(),
                &no_vertices,
                1,
                7,
                SourceMutPointer::null(),
            ),
            Ok(0)
        );
        assert_eq!(
            bIgnoreVertexNonTACN_group(
                &SourceHeap::default(),
                &no_vertices,
                2,
                1,
                SourceMutPointer::null(),
            ),
            Ok(0)
        );
        assert_eq!(
            bIgnoreVertexNonTACN_group(
                &SourceHeap::default(),
                &BN_STRUCT::default(),
                2,
                7,
                SourceMutPointer::null(),
            ),
            Ok(0)
        );

        let mut heap = SourceHeap::default();
        let mut bns = make_graph(&mut heap, 3, &[(0, 1, 0)]);
        bns.type_TACN = TYPE_TACN;
        bns.type_T = TYPE_T;
        bns.type_CN = TYPE_CN;
        {
            let vertices = heap.slice_mut(bns.vert).unwrap();
            vertices[1].type_ = TYPE_T;
            vertices[2].type_ = TYPE_CN;
        }
        let mut switch_values = vec![[NO_VERTEX, -1]; 3];
        switch_values[2] = [5, 0];
        let switch_edges = heap.allocate(switch_values).unwrap();

        assert_eq!(
            bIgnoreVertexNonTACN_group(&heap, &bns, 2, 7, switch_edges),
            Ok(1)
        );
        {
            let vertices = heap.slice_mut(bns.vert).unwrap();
            vertices[1].type_ = TYPE_CN;
            vertices[2].type_ = TYPE_T;
        }
        assert_eq!(
            bIgnoreVertexNonTACN_group(&heap, &bns, 2, 7, switch_edges),
            Ok(1)
        );

        heap.slice_mut(bns.vert).unwrap()[2].type_ = TYPE_CN;
        assert_eq!(
            bIgnoreVertexNonTACN_group(&heap, &bns, 2, 7, switch_edges),
            Ok(0)
        );
        heap.slice_mut(bns.vert).unwrap()[1].type_ = 0;
        assert_eq!(
            bIgnoreVertexNonTACN_group(&heap, &bns, 2, 7, switch_edges),
            Ok(0)
        );
        heap.slice_mut(bns.vert).unwrap()[1].type_ = TYPE_T;

        heap.slice_mut(bns.vert).unwrap()[0].type_ = TYPE_TACN;
        assert_eq!(
            bIgnoreVertexNonTACN_group(&heap, &bns, 2, 7, switch_edges),
            Ok(0)
        );
        heap.slice_mut(bns.vert).unwrap()[0].type_ = 0;
        bns.type_T = 0;
        assert_eq!(
            bIgnoreVertexNonTACN_group(&heap, &bns, 2, 7, switch_edges),
            Ok(0)
        );
        bns.type_T = TYPE_T;

        heap.slice_mut(switch_edges).unwrap()[2] = [NO_VERTEX, -3];
        assert_eq!(
            bIgnoreVertexNonTACN_group(&heap, &bns, 2, 7, switch_edges),
            Ok(0)
        );
        heap.slice_mut(switch_edges).unwrap()[2] = [0, -3];
        assert_eq!(
            bIgnoreVertexNonTACN_group(&heap, &bns, 2, 7, switch_edges),
            Ok(0)
        );
        heap.slice_mut(switch_edges).unwrap()[2] = [5, 0];

        {
            let edge = &mut heap.slice_mut(bns.edge).unwrap()[0];
            edge.neighbor1 = 2;
        }
        assert_eq!(
            bIgnoreVertexNonTACN_group(&heap, &bns, 2, 7, switch_edges),
            Ok(0)
        );
        {
            let edge = &mut heap.slice_mut(bns.edge).unwrap()[0];
            edge.neighbor1 = 0;
        }

        assert_eq!(
            bIgnoreVertexNonTACN_group(&heap, &bns, 2, 7, SourceMutPointer::null(),),
            Err(SourceHeapError::NullPointer)
        );
    }

