    #[test]
    fn source_port__ichi_bns__bnstestandmarkaltbonds__line_1825() {
        fn bns_data(heap: &mut SourceHeap, slots: usize) -> BN_DATA {
            BN_DATA {
                BasePtr: heap.allocate(vec![NO_VERTEX; slots]).unwrap(),
                SwitchEdge: heap.allocate(vec![[NO_VERTEX, -1]; slots]).unwrap(),
                Tree: heap.allocate(vec![0; slots]).unwrap(),
                ScanQ: heap.allocate(vec![NO_VERTEX; slots]).unwrap(),
                Pu: heap.allocate(vec![NO_VERTEX; slots]).unwrap(),
                Pv: heap.allocate(vec![NO_VERTEX; slots]).unwrap(),
                max_num_vertices: slots as i32,
                max_len_Pu_Pv: slots as i32,
                ..BN_DATA::default()
            }
        }

        fn atoms(heap: &mut SourceHeap, bond_type: u8) -> SourceMutPointer<inp_ATOM> {
            let mut left = inp_ATOM {
                valence: 1,
                ..inp_ATOM::default()
            };
            left.neighbor[0] = 1;
            left.bond_type[0] = bond_type;
            let mut right = inp_ATOM {
                valence: 1,
                ..inp_ATOM::default()
            };
            right.neighbor[0] = 0;
            right.bond_type[0] = bond_type;
            heap.allocate(vec![left, right]).unwrap()
        }

        fn configured_bns(heap: &mut SourceHeap) -> BN_STRUCT {
            let mut bns = make_graph(heap, 2, &[(0, 1, BOND_SINGLE as i8)]);
            {
                let edge = &mut heap.slice_mut(bns.edge).unwrap()[0];
                edge.cap = 1;
                edge.flow = 1;
            }
            {
                let vertices = heap.slice_mut(bns.vert).unwrap();
                vertices[0].st_edge.cap = 1;
                vertices[0].st_edge.flow = 1;
                vertices[1].st_edge.cap = 1;
                vertices[1].st_edge.flow = 1;
            }
            bns.max_altp = 1;
            bns.altp[0] = heap.allocate(vec![BNS_ALT_PATH::default(); 6]).unwrap();
            bns.ic = heap.allocate(vec![INCHI_CLOCK::default()]).unwrap();
            bns.ulTimeOutTime = heap.allocate(vec![inchiTime { clockTime: 0 }]).unwrap();
            bns
        }

        let mut mismatch_heap = SourceHeap::default();
        let mut mismatch_bns = configured_bns(&mut mismatch_heap);
        let mismatch_atoms = atoms(&mut mismatch_heap, BOND_SINGLE as u8);
        let mut mismatch_bd = bns_data(&mut mismatch_heap, 6);
        let mismatch_fcd = mismatch_heap
            .allocate(vec![BNS_FLOW_CHANGES::default(); 4])
            .unwrap();
        assert_eq!(
            BnsTestAndMarkAltBonds(
                &mut mismatch_heap,
                &mut mismatch_bns,
                &mut mismatch_bd,
                mismatch_atoms,
                2,
                mismatch_fcd,
                BNS_EF_CHNG_BONDS as i32,
                BOND_DOUBLE as i32,
                0,
            ),
            Ok(0)
        );
        assert_eq!(
            mismatch_heap.slice(mismatch_fcd.as_const()).unwrap()[0].iedge,
            0
        );

        let mut forbidden_heap = SourceHeap::default();
        let mut forbidden_bns = configured_bns(&mut forbidden_heap);
        forbidden_heap.slice_mut(forbidden_bns.edge).unwrap()[0].forbidden = 1;
        let forbidden_atoms = atoms(&mut forbidden_heap, BOND_SINGLE as u8);
        let mut forbidden_bd = bns_data(&mut forbidden_heap, 6);
        let forbidden_fcd = forbidden_heap
            .allocate(vec![BNS_FLOW_CHANGES::default(); 4])
            .unwrap();
        assert_eq!(
            BnsTestAndMarkAltBonds(
                &mut forbidden_heap,
                &mut forbidden_bns,
                &mut forbidden_bd,
                forbidden_atoms,
                2,
                forbidden_fcd,
                BNS_EF_CHNG_BONDS as i32,
                0,
                0,
            ),
            Ok(0)
        );
        assert_eq!(
            forbidden_heap.slice(forbidden_fcd.as_const()).unwrap()[0].iedge,
            0
        );

        let mut fixed_heap = SourceHeap::default();
        let mut fixed_bns = configured_bns(&mut fixed_heap);
        let fixed_atoms = atoms(&mut fixed_heap, BOND_SINGLE as u8);
        let mut fixed_bd = bns_data(&mut fixed_heap, 6);
        let fixed_fcd = fixed_heap
            .allocate(vec![BNS_FLOW_CHANGES::default(); 4])
            .unwrap();
        assert_eq!(
            BnsTestAndMarkAltBonds(
                &mut fixed_heap,
                &mut fixed_bns,
                &mut fixed_bd,
                fixed_atoms,
                2,
                fixed_fcd,
                BNS_EF_CHNG_BONDS as i32,
                BOND_SINGLE as i32,
                0,
            ),
            Ok(0)
        );
        let fixed_edges = fixed_heap.slice(fixed_bns.edge.as_const()).unwrap();
        assert_eq!((fixed_edges[0].cap, fixed_edges[0].flow), (1, 1));
    }

    #[test]
    fn source_port__ichi_bns__remove_alt_bond_marks__line_1987() {
        let mut heap = SourceHeap::default();
        let mut first = inp_ATOM {
            valence: 3,
            ..inp_ATOM::default()
        };
        first.bond_type[0] = (BOND_SINGLE | BOND_MARK_ALT12) as u8;
        first.bond_type[1] = (BOND_DOUBLE | BOND_MARK_ALT23) as u8;
        first.bond_type[2] = (BOND_TRIPLE | BOND_MARK_ALT123) as u8;
        first.bond_type[3] = 0xff;

        let mut second = inp_ATOM {
            valence: 1,
            ..inp_ATOM::default()
        };
        second.bond_type[0] = (BOND_ALTERN | BOND_MARK_ALT13) as u8;
        second.bond_type[1] = 0xfe;

        let mut zero_valence = inp_ATOM {
            valence: 0,
            ..inp_ATOM::default()
        };
        zero_valence.bond_type[0] = 0xfd;

        let atoms = heap.allocate(vec![first, second, zero_valence]).unwrap();
        assert_eq!(remove_alt_bond_marks(&mut heap, atoms, 3), Ok(()));
        let atoms_after = heap.slice(atoms.as_const()).unwrap();
        assert_eq!(atoms_after[0].bond_type[0], BOND_SINGLE as u8);
        assert_eq!(atoms_after[0].bond_type[1], BOND_DOUBLE as u8);
        assert_eq!(atoms_after[0].bond_type[2], BOND_TRIPLE as u8);
        assert_eq!(atoms_after[0].bond_type[3], 0xff);
        assert_eq!(atoms_after[1].bond_type[0], BOND_ALTERN as u8);
        assert_eq!(atoms_after[1].bond_type[1], 0xfe);
        assert_eq!(atoms_after[2].bond_type[0], 0xfd);

        assert_eq!(remove_alt_bond_marks(&mut heap, atoms, -1), Ok(()));
        assert_eq!(heap.slice(atoms.as_const()).unwrap()[0].bond_type[3], 0xff);

        let mut negative_heap = SourceHeap::default();
        let mut negative_valence = inp_ATOM {
            valence: -1,
            ..inp_ATOM::default()
        };
        negative_valence.bond_type[0] = 0xfc;
        let negative_atoms = negative_heap.allocate(vec![negative_valence]).unwrap();
        assert_eq!(
            remove_alt_bond_marks(&mut negative_heap, negative_atoms, 1),
            Ok(())
        );
        assert_eq!(
            negative_heap.slice(negative_atoms.as_const()).unwrap()[0].bond_type[0],
            0xfc
        );

        assert_eq!(
            remove_alt_bond_marks(&mut SourceHeap::default(), SourceMutPointer::null(), 1),
            Err(SourceHeapError::NullPointer)
        );
        let mut short_heap = SourceHeap::default();
        let short_atoms = short_heap.allocate(vec![inp_ATOM::default()]).unwrap();
        assert_eq!(
            remove_alt_bond_marks(&mut short_heap, short_atoms, 2),
            Err(SourceHeapError::PointerOutOfBounds)
        );
    }

